use super::KernelRule;

#[allow(clippy::too_many_lines)]
fn slice_conv_chain() -> Vec<KernelRule> {
    vec![
        // ── Rule 1 (category D — dispatch/scheduling, graph-level fusion
        // scheduling): #383+#398. The launch-bound head of a recurrent
        // layer's decode step — a conv-state GATHER — is skipped at its own
        // position, its read RELOCATED into the CONCAT's launch, which
        // computes the whole downstream tail in ONE kernel and folds the
        // consumer-side STATE WRITE-BACK the graph expressed as a separate
        // CPY; a per-evaluation done-set lets the evaluation loop skip the
        // covered tail. The BACKWARD dataflow twin of the B283 look-ahead. ──
        KernelRule {
            rule_id: "gdn-conv-chain-fusion-gather-relocation-done-set".to_string(),
            gpu_concept: "MECHANISM (a graph-level chain fusion anchored at a mid-chain node: the launch-bound head of a recurrent layer's decode step — a conv-state GATHER — is skipped at its own position and its read is RELOCATED into a later node's launch (the CONCAT it feeds), which then computes the entire downstream tail in ONE kernel, folds a consumer-side STATE WRITE-BACK that the graph expressed as a separate CPY, and records the covered tail in a per-evaluation done-set the evaluation loop skips; every safety condition is a checked conjunct of a pure-function matcher over the node list; category D — dispatch/scheduling, graph-level fusion scheduling): a hybrid gated-delta-net layer's decode step runs five launch-bound kernels between the qkv projection and the GDN op, and the commit's own header names the chain, verbatim (ggml/src/ggml-cuda/ggml-cuda.cu:3069-3072): 'GDN decode conv chain (GGML_CUDA_GDN_FUSION=1, off by default). For one token of one sequence, a hybrid-model' / 'gated delta net layer runs five launch-bound kernels between the qkv projection and the GDN op:' / 'GET_ROWS(conv cache, s_copy) -> RESHAPE -> CONCAT(state, qkv^T) -> CPY(last window -> conv cache)' / '-> SSM_CONV + SILU -> L2_NORM(q/k heads of the SILU output)'. The novel scheduling atom is TWO-SIDED: unlike a forward look-ahead (the sibling rule look-ahead-fusion-precomputed-skip-overlap-walk, which computes a cluster EARLY at the producer's position), this fusion (a) moves a READ forward — the GET_ROWS is skipped where it stands and the cache is read inside the CONCAT's launch — and (b) pulls a consumer's STORE backward — the CPY's cache-row write-back executes inside the same fused launch. Verbatim (ggml-cuda.cu:3073-3079): 'ggml_cuda_ssm_conv_gdn_fused computes all of them in one launch with the same arithmetic per element (bit-identical' / 'outputs). The GET_ROWS is skipped where it stands and registered under its CONCAT (the conv cache is read there' / 'instead: nothing in between may write the cache or the ids); the CONCAT launches the fused kernel and marks the CPY,' / 'SSM_CONV, SILU and L2_NORM done. The CONCAT and SSM_CONV outputs are never materialised, so they must have no other' / 'readers, and every node evaluated between the CONCAT and the L2_NORM (after the fused launch instead of before parts' / 'of it) must not touch any memory the fused kernel reads or writes. Megakernel-style launch removal in the spirit of' / 'Hazy Research's \"no bubbles\" low-latency decode work, applied as a graph-level fusion rather than a persistent kernel.' THE TWO-PHASE REGISTRATION is the mechanism that makes a non-adjacent chain fusable on a linear node list: a per-evaluation registry on the backend context (common.cuh:1600-1604, verbatim: 'GDN decode conv chain fused into one launch (GGML_CUDA_GDN_FUSION=1): the conv-state GET_ROWS is skipped and' / 'registered under the CONCAT it feeds; the CONCAT launches the fused kernel, which also computes the conv-state CPY,' / 'SSM_CONV + SILU and the q/k L2_NORM, and those nodes are marked done. Keyed by node identity, valid for one graph' / 'evaluation, owned by the evaluating context (reset with the other per-evaluation registries).' — the struct carries gathers ('// CONCAT -> the GET_ROWS it replaces') and done ('// nodes computed by a fused launch'), both cleared in reset()). Phase 1 at the GET_ROWS (ggml-cuda.cu:3329, verbatim: '// at the conv-state GET_ROWS: skip it when its CONCAT will run the fused chain'): the gate is fusion-enabled AND NVIDIA (verbatim :3331: `if (!ggml_cuda_gdn_fusion_enabled() || !GGML_CUDA_CC_IS_NVIDIA(ggml_cuda_info().devices[ctx.device].cc)) {`), then a bounded forward scan — verbatim :3335: `for (int j = node_idx + 1; j < cgraph->n_nodes && j < node_idx + 128; ++j) {` — for a CONCAT whose src[0] is a RESHAPE of this GET_ROWS; the full matcher runs and on success the pair is registered and the gather launch is skipped. Phase 2 at the CONCAT (verbatim :3350: '// at the CONCAT whose GET_ROWS was skipped: one launch for the chain') re-runs the same matcher — it is 'a pure function of the graph' — and on agreement launches the fused kernel and marks the tail done (:3365-3368: `reg.done.insert(cgraph->nodes[p.i_cpy]);` … `reg.done.insert(cgraph->nodes[p.i_l2]);`). The evaluation loop consumes both phases with an empty()-short-circuited skip set and two dedicated arms: done.count(node) → continue; GET_ROWS arm and CONCAT arm behind `!is_concurrent_event_active`. THE MATCHER'S ADMISSION is conjunctive and every conjunct is load-bearing (the ok-chain short-circuits; drop one and the fusion must not fire). (1) THE ANCHOR: the CONCAT must be dim-0 (`ggml_get_op_params_i32(cc, 0) != 0` refuses), F32, not a graph output, contiguous, 2D — verbatim :3124-3125: `if (cc->op != GGML_OP_CONCAT || ggml_get_op_params_i32(cc, 0) != 0 || cc->type != GGML_TYPE_F32 ||` / `(cc->flags & GGML_TENSOR_FLAG_OUTPUT) || !ggml_is_contiguous(cc) || cc->ne[2] != 1 || cc->ne[3] != 1) {` — with the template-width admission verbatim :3130: `if (d_conv < 3 || d_conv > 5 || C > INT_MAX / 8) {` (the kernel instantiates d_conv 3/4/5 only; GGML_ABORT elsewhere, ssm-conv.cu:297). (2) THE RELOCATED GATHER: src[0] is RESHAPE(GET_ROWS(cache, ids)) with exact shapes [d_conv-1, C], the cache an F32 flat-row tensor, the ids a ONE-ELEMENT I32 tensor; position checks (ggml_cuda_find_node) plus UNIT USE-COUNTS on the gather and its reshape — verbatim :3151: `if (i_gr < 0 || i_s0 < 0 || ggml_node_get_use_count(cgraph, i_gr) != 1 || ggml_node_get_use_count(cgraph, i_s0) != 1) {` — the lifetime proof that the never-materialized gather row has no second reader. (3) THE FOLDED STORE: the next real node after the CONCAT must be a CPY whose source is a VIEW of the concat at offset one float with the concat's row stride, and whose destination is ONE WHOLE ROW OF THE SAME CACHE — verbatim :3187-3189: '// the destination is one whole cache row: the same row the state is read from, or a disjoint one' then the containment conjunct `r_dst.beg < r_cache.beg || r_dst.end > r_cache.end || (r_dst.beg - r_cache.beg) % cache->nb[1] != 0 ||` / `r_dst.end - r_dst.beg != (uintptr_t) cache->ne[0] * sizeof(float)) {`; the concat itself must have use_count exactly 2 (the window view + the conv). Read-row ≠ write-row is admitted (the test matrix pins it); read-row == write-row is made safe by per-thread read-before-write inside the kernel (ssm-conv.cu:243-244, verbatim: '// conv-state write-back: the last d_conv - 1 inputs (the same row when ids[0] is the destination row: this thread' / 'read its values above)'). (4) THE CONSUMER CHAIN: an SSM_CONV consuming the concat within 64 nodes (`j < i_cpy + 64`), F32, unit use-count, weights [d_conv, C] F32; followed IMMEDIATELY by a SILU unary of that conv; then the next real node an L2_NORM over a leading zero-offset contiguous VIEW of the silu output, with the shape admission verbatim :3237: `if (row_len % WARP_SIZE != 0 || row_len >= 1024 || C % row_len != 0 || n_l2 > C || eps < 0.0f) {` (mirrored launch-side by ssm-conv.cu:282, verbatim: `GGML_ASSERT(a.row_len % WARP_SIZE == 0 && a.row_len < 1024 && a.n_channels % a.row_len == 0 && a.n_l2 % a.row_len == 0);`). (5) THE MEMORY GATES with one documented carve-out — verbatim :3241: '// memory: outputs against inputs (the SILU may overwrite the new token in place, element for element)' and :3249: `const bool y_in_place = silu->data == x->data && x->nb[1] == sizeof(float);` — silu-over-x is legal ONLY in the exact element-for-element form; every other output/input pair (y, l2, dst vs x, cache, w, ids, each other) must be disjoint byte ranges. (6) THE READ-RELOCATION WINDOW: verbatim :3259: '// between the GET_ROWS and the CONCAT nothing may write the cache or the ids (the read moves to the CONCAT)' — the relocated read must observe the same bytes the skipped gather would have. (7) THE POST-LAUNCH INTERPOSITION WINDOW: verbatim :3270: '// nodes evaluated after the fused launch instead of before parts of it: no shared memory with the chain' — every real node between the CONCAT and the L2_NORM (excluding the three covered ones and view/noop) must neither write nor read any chain buffer (its own range against all eight chain ranges; each src against the write-target set {cache, y, l2, concat, conv} — foreign READS of the stable inputs x/w/ids are permitted, the src-side list deliberately omits them). (8) THE CONCURRENCY GATE, verbatim :3294: '// concurrent streams would run other nodes alongside' — any concurrent stream event mapping any of the six chain nodes refuses. BIT IDENTITY BY ORDERING REPLAY, one thread per channel: the fused kernel re-executes each unfused kernel's per-element expression order, verbatim (ssm-conv.cu:208-212): 'GDN decode conv chain in one launch (see ggml_cuda_gdn_conv_fusion in ggml-cuda.cu): the conv-state row gather, the' / 'concat with the new token, the conv-state write-back, the depthwise conv + SiLU and the L2 norm of the q/k heads.' / 'One thread per channel, one block per L2 row (head). Every value is computed with the same expression, in the same' / 'order, as the unfused kernels: the conv sum as ssm_conv_f32 (token 0, no bias), the L2 norm as l2_norm_f32 with' / 'WARP_SIZE threads (per-lane strided partial sums, then the warp butterfly), so the outputs are bit-identical.' — including the absent-bias identity verbatim :250: `const float b = 0.0f; // ssm_conv_f32 adds its (absent) bias as 0.0f`, and the block-uniform early-out verbatim :261: `return; // a v channel block: no L2 norm (block-uniform)`. End-to-end proof, verbatim (commit message #383): 'Bit-exact: greedy tokens and top-k logprobs are identical with it on and off, including MTP.' Tests are WHOLE-GRAPH and check all three surviving outputs (test-backend-ops.cpp:4139-4142, verbatim: 'The decode conv chain of a gated delta net layer (one token, one sequence), as the hybrid models build it:' / 'GET_ROWS (conv state row) -> CONCAT with the new token -> CPY of the last window back into a cache row,' / 'SSM_CONV -> SILU -> L2_NORM of the leading q/k heads. The CUDA backend can run it as one launch' / '(GGML_CUDA_GDN_FUSION=1); the L2_NORM, the SILU output and the written cache row are all checked.'), across d_conv {3,4,5}, head dims {32..256}, and both cache-row postures — in place (src_row == dst_row) and across rows (1→2, 2→0, 0→1) (:10067, verbatim: '// GDN decode conv chain: in place and across cache rows, several conv widths and head sizes'). ENV ARC (the opt-in→default flip is #398's entire content): #383 ships opt-in, verbatim (ggml-cuda.cu:3081-3082): `static const bool enabled = getenv(\"GGML_CUDA_GDN_FUSION\") != nullptr &&` / `atoi(getenv(\"GGML_CUDA_GDN_FUSION\")) != 0;` — absent env = OFF. #398 flips to demote-only, verbatim (ggml-cuda.cu:3083-3086): `static const bool enabled = [] {` / `const char * env = getenv(\"GGML_CUDA_GDN_FUSION\");` / `return env == nullptr || atoi(env) != 0;` / `}();` — absent env = ON, `=0` disables; the same flip lands in both comments (ggml-cuda.cu:3069 at #398; common.cuh:1600; both test-case comments). MEASURED (source-reported, H200 — provenance, never bars): #383: 'decode +5-10% (2B to 27B) and 9B +7.2%, with 90-240 fewer kernels per token'; #398: '9B decode +7.9% (353 -> 381 tok/s), 27B about +7.5%', 'Bit-exact: tokens are identical to the unfused path on 2B, 4B, 9B and 27B.' SCOPE DISCLOSURE: at the two read commits the chain is ONE token; by #398's tree the stack had ALREADY extended the fusion to speculative verify widths (the intermediate `820701ce3` #399, 'verify widths (1-16 tokens, rollback snapshots)'; #398's own context lines read 'For n_t tokens of one sequence (a decode step, n_t = 1, or a speculative verify step, n_t = 2..GGML_CUDA_GDN_CONV_MAX_TOKENS)') — the extension is DISCLOSED, not owned by these two pins. DECISION CONTENT: (a) the anchor-plus-registry shape — a fusion whose head node (the gather) fires at a DIFFERENT evaluation position than its body (the CONCAT) is admitted by a two-phase registry keyed on node identity, valid one evaluation, reset with the sibling registries; (b) the READ-RELOCATION conjunct — moving a read forward requires a write-exclusion walk over the relocation window (nothing between gather and concat may write the read's bytes), distinct from an early-write's aliasing walk; (c) the FOLDED CONSUMER STORE — a downstream CPY into a whole row of the read's own cache folds into the launch, admitted by row containment + alignment + the in-place read-before-write argument, with read-row ≠ write-row admitted and pinned by tests; (d) never-materialized intermediates (concat, conv outputs) demand unit use-counts on every producer and the unmaterialized tail; (e) the interposition walk prices BOTH directions over the covered window with the stable-input read exemption; (f) the fallback is materialize-and-run-unfused, never a wrong fused launch; (g) bit identity is ordering replay per element (same conv sum form, same L2 reduction topology), verified by whole-graph tests checking every surviving output; (h) the promotion arc is opt-in → demote-only default by an env-polarity flip, kill switch GGML_CUDA_GDN_FUSION=0. CLASS SIGNATURE: a linear node-list evaluation loop with node use-counts and byte-range identity; a launch-bound op chain whose head is a gather from a persistent state cache and whose tail includes a write-back into that same cache. REGIME: recurrent/conv-state decode chains (GDN/SSM layer preambles); decode-shaped graphs where launch count dominates; graph builders where the gather's consumer sits within a bounded lookahead. ANTI-REGIME: any writer of the cache or the index between the gather and its consumer; a second reader of any unmaterialized intermediate; the write-back destination not a whole aligned cache row; concurrent stream events touching the chain; conv widths outside the template set; graphs where the concat or conv output is a pinned graph output. KINSHIP (do not double-count): look-ahead-fusion-precomputed-skip-overlap-walk (entries_gpu_128, B283 — same fork, same family) owns the FORWARD look-ahead atom (compute early at the producer, precomputed set, early-write overlap walk); THIS owns the BACKWARD atom — gather relocation (a read moved into a later launch) + a consumer store folded backward + the relocation-window write-exclusion walk — same skip-set machinery, opposite dataflow direction; cite both for the family, own the direction. whole-step-gdn-decode-window-one-launch (entries_gpu_126, B278) owns the WHOLE-LAYER-STEP boundary (conv+norms+recurrence+output norm in one monolithic Metal/MLX kernel, S≤16 window); THIS owns the CUDA GRAPH-LEVEL conv-chain boundary only — no recurrence, the GDN op itself stays a separate launch — and the admission lives in a matcher, not a monolithic kernel; adjacent boundaries, compose not merge. fused-conv-state-shift-dot-silu (entries_gpu_02) owns the decode conv slide+dot+silu kernel PIECE; THIS owns the graph admission that folds gather/concat/write-back/L2 around it. bit-exact-dispatch-fusion-boundary-emulation (entries_gpu_12) owns the boundary-EMULATION pole (re-materialize intermediates + fences); THIS is the never-materialize ordering-replay pole — the oracle family's two arms. gdn-transition-replay-log-commit-many (entries_gpu_08) + lazy-rollback-journaled-window-replay-replaces-eager-state-snapshots (entries_gpu_105) own journal/replay of GDN transitions and rollback states — different objects entirely. The #379 sibling (ggml_cuda_try_gdn_gather_skip, the recurrent-state gather folded into the GDN kernel) is the registry-pattern precedent this commit explicitly stacks on (its eval-loop arm sits directly below the new one at ggml-cuda.cu:5353); it is quoted in the corpus only as a PDL-wait instance (grid-dependency-wait-scoped-to-dependent-operands, entries_gpu_23 rider) — no owner, do not re-own here. GREP EVIDENCE: 'conv.?chain|conv_chain' → ZERO corpus hits; 'ssm_conv|ssm-conv' → ONE hit (entries_gpu_07, the DFLASH_QWEN35 folded-kernel mention — different repo, not an owner); 'GDN_FUSION|97ea5aee|bf8c069|mul_mat_vec_f_pair|gdn_gather' → TWO hits, neither an owner (entries_gpu_128's MEASURED block cites '#383 (GGML_CUDA_GDN_FUSION on and off)' as a validation CONTEXT; entries_gpu_23's rider quotes ggml_cuda_try_gdn_gather_skip — the #379 gather, a PDL instance); 'state write.?back|writeback' → the write-amplification/lifetime classes only (wide-row-copy gpu_11, lazy-rollback gpu_105, skip-unchanged-writes gpu_07) — no chain-fusion owner. NotBenchable here (llama.cpp CUDA graph-builder sources; the corpus serves no CUDA graph validator — the matcher conjuncts, the two interference walks and the ordering replay are CPU-testable and ARE the fixtures; the H200 figures are source-reported provenance on foreign silicon, never an adoption bar). Source: PrismML/llama.cpp commit 97ea5aeee1 (#383, bri-prism, 2026-10-24, MIT lineage) + commit bf8c069fde (#398, the default-on flip) — ggml/src/ggml-cuda/ggml-cuda.cu (the matcher, both phase arms, the eval-loop integration, the env flip), common.cuh (the registry), ssm-conv.cu + ssm-conv.cuh (the fused kernel + args), mmvf.cu (the twin rule's launcher, same flag), tests/test-backend-ops.cpp (test_gdn_conv_chain, whole-graph). Batch 295 / Plan 300 / Research 333.".to_string(),
            ref_shape: "// ref_shape: the unfused decode chain — one launch per node,\n// strictly in graph order; the gather materializes a cache row the\n// concat immediately re-reads, and the write-back is its own launch.\n#![allow(dead_code)]\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Op { GetRows, Reshape, Concat, Cpy, SsmConv, Silu, L2Norm, Gdn, Other }\n\nstruct Node { op: Op, use_count: usize, is_output: bool }\n\n/// one conv chain as the graph builder emits it (1 token, 1 sequence)\nfn conv_chain() -> Vec<Node> {\n    vec![\n        Node { op: Op::GetRows, use_count: 1, is_output: false }, // 0: cache row\n        Node { op: Op::Reshape, use_count: 1, is_output: false }, // 1\n        Node { op: Op::Concat,  use_count: 2, is_output: false }, // 2: view + conv\n        Node { op: Op::Cpy,     use_count: 1, is_output: false }, // 3: write-back\n        Node { op: Op::SsmConv, use_count: 1, is_output: false }, // 4\n        Node { op: Op::Silu,    use_count: 1, is_output: false }, // 5\n        Node { op: Op::L2Norm,  use_count: 1, is_output: false }, // 6: q/k heads\n        Node { op: Op::Gdn,     use_count: 1, is_output: true  }, // 7\n    ]\n}\n\n/// the naive loop: one launch per real node, every chain kernel alone\nfn evaluate_naive(graph: &[Node]) -> u32 {\n    let mut launches = 0;\n    for n in graph {\n        if n.op == Op::Reshape || n.op == Op::Other { continue; } // view/noop\n        launches += 1;\n    }\n    launches\n}\n\n#[test]\nfn the_chain_pays_a_launch_per_real_node() {\n    let g = conv_chain();\n    // get_rows, concat, cpy, ssm_conv, silu, l2_norm + the gdn op = 7\n    assert_eq!(evaluate_naive(&g), 7);\n}\n".to_string(),
            opt_pattern: "// opt_pattern: two-phase graph fusion. Phase 1 at the GATHER: a bounded\n// forward scan for the CONCAT whose first operand traces back through\n// its reshape to THIS gather; the full pure-function matcher runs, and\n// on success the pair is registered and the gather is skipped. Phase 2\n// at the CONCAT: re-match, launch ONE kernel computing concat +\n// write-back + conv + silu + l2 with the gather's read RELOCATED inside\n// it, mark the tail done. Every gate below is a load-bearing conjunct\n// of the upstream matcher; the fallback materializes the skipped gather\n// and runs unfused, never a wrong fused launch.\n#![allow(dead_code)]\n\nuse std::collections::{HashMap, HashSet};\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Op { GetRows, Reshape, Concat, Cpy, SsmConv, Silu, L2Norm, Gdn, View, Other }\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nstruct Range { beg: usize, end: usize }\n\nimpl Range {\n    fn overlaps(self, o: Range) -> bool {\n        self.beg < self.end && o.beg < o.end && self.beg < o.end && o.beg < self.end\n    }\n}\n\nstruct Node {\n    op: Op,\n    out: Range,          // this node's output buffer\n    srcs: Vec<Range>,    // operand buffers\n    use_count: usize,\n    is_output: bool,\n}\n\nstruct Cache { row: Range, row_stride: usize }\n\nstruct Plan { gather: usize, cpy: usize, conv: usize, silu: usize, l2: usize }\n\n/// the pure-function matcher at the CONCAT (index `ic`). Every early\n/// return is the upstream ok-chain short-circuit.\nfn match_conv_chain(g: &[Node], ic: usize, cache: &Cache, d_conv: usize) -> Option<Plan> {\n    let cc = &g[ic];\n    // anchor: dim-0 f32 contiguous concat, not an output, exactly two\n    // readers (the write-back window view + the conv); d_conv rides a\n    // kernel template instantiated for 3/4/5 only.\n    if cc.op != Op::Concat || cc.is_output || cc.use_count != 2 { return None; }\n    if !(3..=5).contains(&d_conv) { return None; }\n    // relocated gather: reshape(get_rows(cache, ids)) feeds src[0].\n    // Position checks (walk back through the operand chain), then UNIT\n    // use-counts: the never-materialized gather row must have no second\n    // reader.\n    let s0 = *cc.srcs.first()?;\n    if s0.end - s0.beg != (d_conv - 1) * 4 { return None; }\n    let i_s0 = (0..ic).rev().find(|&k| g[k].out == s0)?;\n    if g[i_s0].op != Op::Reshape || g[i_s0].use_count != 1 { return None; }\n    let r0 = *g[i_s0].srcs.first()?;\n    let gather = (0..i_s0).rev().find(|&k| g[k].out == r0)?;\n    if g[gather].op != Op::GetRows || g[gather].use_count != 1 || g[gather].is_output {\n        return None;\n    }\n    // the folded store: the next real node is a CPY whose destination is\n    // ONE WHOLE cache row, row-aligned inside the cache.\n    let mut icpy = ic + 1;\n    while icpy < g.len() && matches!(g[icpy].op, Op::View | Op::Other) { icpy += 1; }\n    let cpy = g.get(icpy)?;\n    if cpy.op != Op::Cpy || cpy.is_output || cpy.use_count != 1 { return None; }\n    let dst = cpy.srcs[1];\n    let one_row = cache.row_stride * 4; // one f32 cache row in bytes\n    let aligned = dst.beg >= cache.row.beg\n        && dst.end <= cache.row.end\n        && (dst.beg - cache.row.beg) % cache.row_stride == 0\n        && dst.end - dst.beg == one_row;\n    if !aligned { return None; }\n    // consumer chain: an ssm_conv over the concat within 64 nodes, then\n    // silu, then the next real node the l2 norm of the leading heads.\n    let mut iconv = None;\n    for j in icpy + 1..g.len().min(icpy + 64) {\n        if g[j].op == Op::SsmConv && g[j].srcs.contains(&cc.out) { iconv = Some(j); break; }\n    }\n    let iconv = iconv?;\n    if iconv + 2 >= g.len() { return None; }\n    let (conv, silu) = (&g[iconv], &g[iconv + 1]);\n    if conv.use_count != 1 || silu.op != Op::Silu || silu.use_count != 1 { return None; }\n    let mut il2 = iconv + 2;\n    while il2 < g.len() && matches!(g[il2].op, Op::View | Op::Other) { il2 += 1; }\n    if il2 >= g.len() { return None; }\n    let l2node = &g[il2];\n    if l2node.op != Op::L2Norm || l2node.is_output || l2node.use_count != 1 { return None; }\n    // memory gates: outputs against inputs, two sanctioned pairs -- the\n    // silu may overwrite the new token element for element, and the\n    // write-back lands in the cache it read (a whole aligned row, read\n    // before write inside the ONE launch; read-row != write-row is the\n    // across-rows posture, same carve-out).\n    let y_in_place = silu.out == cc.srcs[1];\n    let inputs = [cc.srcs[1], cache.row, conv.srcs[1]];\n    let outs = [silu.out, l2node.out, dst];\n    for o in outs { for i in inputs {\n        let sanctioned = (y_in_place && o == silu.out && i == cc.srcs[1])\n            || (o == dst && i == cache.row);\n        if o.overlaps(i) && !sanctioned { return None; }\n    } }\n    // read-relocation window: between the get_rows and the concat\n    // nothing may WRITE the cache or the ids (the read moves to the\n    // concat; a view materializes nothing and is exempt).\n    for t in &g[gather + 1..ic] {\n        if t.op == Op::View { continue; }\n        if t.out.overlaps(cache.row) { return None; }\n    }\n    // interposition window: every real node evaluated after the fused\n    // launch instead of before parts of it owns no chain memory -- its\n    // own range against the chain's, each source against the write\n    // targets (foreign READS of the stable inputs are permitted, the\n    // src-side list deliberately omits them).\n    let chain = [cc.out, cache.row, silu.out, l2node.out, conv.out];\n    let write_targets = [cache.row, silu.out, l2node.out, cc.out, conv.out];\n    for t in &g[ic + 1..il2] {\n        if matches!(t.op, Op::View | Op::Other | Op::Cpy | Op::SsmConv | Op::Silu) { continue; }\n        if chain.iter().any(|r| t.out.overlaps(*r)) { return None; }\n        for s in &t.srcs {\n            if write_targets.iter().any(|r| s.overlaps(*r)) { return None; }\n        }\n    }\n    Some(Plan { gather, cpy: icpy, conv: iconv, silu: iconv + 1, l2: il2 })\n}\n\n#[derive(Default)]\nstruct Registry { gathers: HashMap<usize, usize>, done: HashSet<usize> }\n\n/// phase 1: at the gather. A bounded forward scan for the concat whose\n/// first operand traces back through its reshape to THIS gather; the\n/// full matcher runs, on success the pair is registered and the launch\n/// is skipped. A traced candidate that fails the match decides\n/// negatively: the gather materializes.\nfn try_gather_skip(reg: &mut Registry, g: &[Node], i: usize, cache: &Cache, d_conv: usize) -> bool {\n    for j in i + 1..g.len().min(i + 128) {\n        if g[j].op != Op::Concat { continue; }\n        let s0 = match g[j].srcs.first() { Some(r) => *r, None => continue };\n        let Some(ir) = (0..j).rev().find(|&k| g[k].out == s0) else { continue };\n        if g[ir].op != Op::Reshape { continue; }\n        let Some(r0) = g[ir].srcs.first() else { continue };\n        if *r0 != g[i].out { continue; }\n        if let Some(p) = match_conv_chain(g, j, cache, d_conv) {\n            if p.gather == i { reg.gathers.insert(j, i); return true; }\n        }\n        return false; // the candidate failed the full match\n    }\n    false\n}\n\n/// phase 2: at the concat. Re-match, launch fused, mark done. A\n/// mismatch materializes the skipped gather and runs unfused.\nfn try_fused_at_concat(\n    reg: &mut Registry, g: &[Node], ic: usize, cache: &Cache, d_conv: usize,\n    launches: &mut u32, materialized: &mut bool,\n) -> bool {\n    let Some(gather) = reg.gathers.get(&ic).copied() else { return false };\n    match match_conv_chain(g, ic, cache, d_conv) {\n        Some(p) if p.gather == gather => {\n            *launches += 1; // ONE launch: concat + write-back + conv + silu + l2\n            reg.done.insert(p.cpy);\n            reg.done.insert(p.conv);\n            reg.done.insert(p.silu);\n            reg.done.insert(p.l2);\n            true\n        }\n        _ => { *materialized = true; *launches += 1; false } // gather back, unfused\n    }\n}\n\nfn evaluate(reg: &mut Registry, g: &[Node], cache: &Cache, d_conv: usize, enabled: bool) -> u32 {\n    let mut launches = 0;\n    let mut materialized = false;\n    for i in 0..g.len() {\n        if reg.done.contains(&i) { continue; } // computed by a fused launch\n        match g[i].op {\n            Op::GetRows if enabled => {\n                if try_gather_skip(reg, g, i, cache, d_conv) { continue; }\n                launches += 1; // the gather materializes\n            }\n            Op::Concat if enabled => {\n                if try_fused_at_concat(reg, g, i, cache, d_conv, &mut launches, &mut materialized) {\n                    continue;\n                }\n                launches += 1; // unfused concat\n            }\n            Op::Reshape | Op::View | Op::Other => {}\n            _ => launches += 1,\n        }\n    }\n    launches\n}\n\nfn chain_graph() -> (Vec<Node>, Cache) {\n    let cache = Cache { row: Range { beg: 0, end: 64 }, row_stride: 16 };\n    let src = Range { beg: 100, end: 116 };\n    let n = |op: Op, out: Range, srcs: Vec<Range>, uc: usize, outp: bool| Node {\n        op, out, srcs, use_count: uc, is_output: outp,\n    };\n    let g = vec![\n        n(Op::GetRows, Range { beg: 100, end: 116 }, vec![cache.row], 1, false),   // 0\n        n(Op::Reshape, Range { beg: 100, end: 116 }, vec![src], 1, false),         // 1\n        n(Op::Concat, Range { beg: 200, end: 264 }, vec![src, Range { beg: 900, end: 964 }], 2, false), // 2\n        n(Op::Cpy, Range { beg: 300, end: 316 }, vec![Range { beg: 216, end: 232 }, cache.row], 1, false), // 3\n        n(Op::SsmConv, Range { beg: 400, end: 416 }, vec![Range { beg: 200, end: 264 }, Range { beg: 950, end: 1000 }], 1, false), // 4\n        n(Op::Silu, Range { beg: 500, end: 516 }, vec![Range { beg: 400, end: 416 }], 1, false), // 5\n        n(Op::L2Norm, Range { beg: 600, end: 616 }, vec![Range { beg: 500, end: 516 }], 1, false), // 6\n        n(Op::Gdn, Range { beg: 700, end: 764 }, vec![Range { beg: 600, end: 616 }], 1, true), // 7\n    ];\n    (g, cache)\n}\n\n#[test]\nfn the_fused_chain_pays_one_launch_and_the_gdn_launch() {\n    let (g, cache) = chain_graph();\n    let mut reg = Registry::default();\n    // seven launches -> ONE fused launch + the gdn op.\n    assert_eq!(evaluate(&mut reg, &g, &cache, 5, true), 2);\n    assert!(reg.done.contains(&3) && reg.done.contains(&4) && reg.done.contains(&6));\n    // read-row != write-row is admitted: the write-back aimed at the\n    // cache's SECOND row still folds (the across-rows posture).\n    let (mut g2, mut cache2) = chain_graph();\n    cache2.row = Range { beg: 1200, end: 1328 }; // two rows of 16 f32\n    g2[0].srcs[0] = Range { beg: 1200, end: 1264 }; // the gather reads row 0\n    g2[3].srcs[1] = Range { beg: 1264, end: 1328 }; // the write-back lands row 1\n    let mut reg2 = Registry::default();\n    assert_eq!(evaluate(&mut reg2, &g2, &cache2, 5, true), 2);\n    // a View between the concat and the cpy: the fold looks past views\n    // to the next REAL node and still fires.\n    let (mut g3, cache3) = chain_graph();\n    g3.insert(3, Node { op: Op::View, out: Range { beg: 216, end: 232 }, srcs: vec![Range { beg: 200, end: 264 }], use_count: 1, is_output: false });\n    let mut reg3 = Registry::default();\n    assert_eq!(evaluate(&mut reg3, &g3, &cache3, 5, true), 2);\n}\n\n#[test]\nfn disabled_or_unmatched_keeps_every_launch() {\n    let (g, cache) = chain_graph();\n    let mut reg = Registry::default();\n    assert_eq!(evaluate(&mut reg, &g, &cache, 5, false), 7); // the flag arm\n    // a write-back destination OUTSIDE the cache refuses the fold and\n    // the fallback materializes the gather: unfused, never a wrong\n    // fused launch.\n    let (mut g2, cache2) = chain_graph();\n    g2[3].srcs[1] = Range { beg: 5000, end: 5016 }; // a foreign row\n    let mut reg2 = Registry::default();\n    assert_eq!(evaluate(&mut reg2, &g2, &cache2, 5, true), 7);\n    // a concat with a THIRD reader: the never-materialized concat\n    // output would be observed, the fold refuses.\n    let (mut g3, cache3) = chain_graph();\n    g3[2].use_count = 3;\n    let mut reg3 = Registry::default();\n    assert_eq!(evaluate(&mut reg3, &g3, &cache3, 5, true), 7);\n    // d_conv outside the kernel template set (3/4/5) refuses too.\n    let mut reg4 = Registry::default();\n    assert_eq!(evaluate(&mut reg4, &g, &cache, 6, true), 7);\n}\n\n#[test]\nfn a_cache_write_between_gather_and_concat_refuses() {\n    // an unrelated node between the gather and the concat whose output\n    // overlaps the cache: the relocated read could observe different\n    // bytes than the skipped gather would have -- the write-exclusion\n    // walk refuses, the gather materializes, nothing fuses.\n    let (mut g, cache) = chain_graph();\n    g.insert(1, Node { op: Op::Other, out: cache.row, srcs: vec![], use_count: 1, is_output: false });\n    let mut reg = Registry::default();\n    assert_eq!(evaluate(&mut reg, &g, &cache, 5, true), 7);\n    // the twin: the same node writing a FOREIGN range leaves the\n    // relocation window clean and the fusion fires.\n    let (mut g2, cache2) = chain_graph();\n    g2.insert(1, Node { op: Op::Other, out: Range { beg: 5000, end: 5064 }, srcs: vec![], use_count: 1, is_output: false });\n    let mut reg2 = Registry::default();\n    assert_eq!(evaluate(&mut reg2, &g2, &cache2, 5, true), 2);\n    // a node evaluated between the concat and the l2 norm may still READ\n    // a stable input (the conv weights): the interposition walk prices\n    // its own range and its sources against the WRITE targets only.\n    let (mut g3, cache3) = chain_graph();\n    g3.insert(6, Node { op: Op::Other, out: Range { beg: 3000, end: 3016 }, srcs: vec![Range { beg: 950, end: 1000 }], use_count: 1, is_output: false });\n    let mut reg3 = Registry::default();\n    assert_eq!(evaluate(&mut reg3, &g3, &cache3, 5, true), 2);\n}\n".to_string(),
        },
        // ── Rule 2 (category C — fusion/launch, the paired-single-column
        // mat-vec admission): #383+#398's mmvf half. Two INDEPENDENT
        // single-column mat-vecs over the SAME activation, consecutive in
        // the graph, execute as ONE launch of the SAME vector kernel — the
        // second weight addressed as the first plus a byte offset expressed
        // as a CHANNEL STRIDE, the shared activation BROADCAST at channel
        // stride zero; bit-identical by template identity. ──
        KernelRule {
            rule_id: "same-activation-mmvf-pair-channel-stride-broadcast".to_string(),
            gpu_concept: "MECHANISM (two INDEPENDENT single-column mat-vecs over the SAME activation, consecutive in the graph, execute as ONE launch of the SAME vector kernel — the second weight tensor is addressed as the first weight plus a byte offset expressed as a CHANNEL STRIDE, and the shared activation is BROADCAST across the two channels with channel stride zero; zero arithmetic changes, zero layout requirements, bit-identical by template identity; category C — fusion/launch, the pair-launch admission): the GDN gated-delta-net layer projects its normalized state through two sibling single-column mat-vecs — the alpha and beta gates — and at decode these are two consecutive MUL_MAT nodes over one activation; two launches back-to-back is pure launch cost. The pair launcher's own header states the whole mechanism, verbatim (ggml/src/ggml-cuda/mmvf.cu:884-888): 'Two independent mat-vecs that share src1 and the weight type, shape and strides, as one launch of the same kernel:' / 'the second weight becomes channel 1 (its offset from the first is the channel stride, src1 is broadcast with channel' / 'stride 0). Every row runs the same template instance with the same block size as a single launch would, so the' / 'results are bit-identical. Returns false (nothing launched) when the pair does not qualify.' — the declarative twin at the header seam (mmvf.cuh:15-16, verbatim: '// two independent mat-vecs sharing src1 and the weight layout, as one launch (bit-identical); false: not launched'). The graph-level matcher frames the instance, verbatim (ggml-cuda.cu:4173-4174): 'Two consecutive independent F32/F16/BF16 mat-vecs on the same activation (the GDN alpha and beta projections, which' / 'the fused GDN op consumes raw) as one launch, GGML_CUDA_GDN_FUSION=1. Returns the number of nodes consumed.' THE ADMISSION is the decision content — every conjunct names a legality or bit-exactness condition (mmvf.cu:892-900, verbatim): `if (dst1->src[1] != src1 || a->type != b->type || !ggml_are_same_shape(a, b) || !ggml_are_same_stride(a, b) ||` / `(a->type != GGML_TYPE_F32 && a->type != GGML_TYPE_F16 && a->type != GGML_TYPE_BF16) ||` / `src1->type != GGML_TYPE_F32 || dst0->type != GGML_TYPE_F32 || dst1->type != GGML_TYPE_F32 ||` / `a->ne[2] != 1 || a->ne[3] != 1 || src1->ne[1] != 1 || src1->ne[2] != 1 || src1->ne[3] != 1 ||` / `src1->nb[0] != sizeof(float) || !ggml_are_same_shape(dst0, dst1) || !ggml_is_contiguous(dst0) ||` / `!ggml_is_contiguous(dst1) || dst0->ne[1] != 1 || dst0->ne[2] != 1 || dst0->ne[3] != 1 ||` / `a->nb[0] != ggml_type_size(a->type)) { return false; }` — IDENTICAL POINTER for the shared activation (`dst1->src[1] != src1`), identical weight type/shape/strides, weights 2D only, the activation a single F32 vector, each output exactly ONE column of F32, contiguous everything, weight rows contiguous in the element size. THE OFFSET ARITHMETIC GATE makes the channel-stride trick legal, verbatim (mmvf.cu:904-905): `if (dx % (int64_t) ts != 0 || dd % (int64_t) sizeof(float) != 0 || dx == 0 || dd == 0 ||` / `std::abs(dx / (int64_t) ts) > INT_MAX || std::abs(dd / (int64_t) sizeof(float)) > INT_MAX) {` — the byte distance between the two weight allocations (and between the two outputs) must be nonzero (aliased or in-place pairs refuse), element-size aligned (it becomes an integer element stride inside the kernel), and representable in an int (the kernel's stride parameter width). THE PRECISION-AGREEMENT GATE, verbatim (mmvf.cu:910-911): `const enum ggml_prec prec = fast_fp16_available(cc) ? ggml_prec(dst0->op_params[0]) : GGML_PREC_F32;` / `if (prec != (fast_fp16_available(cc) ? ggml_prec(dst1->op_params[0]) : GGML_PREC_F32)) {` — both products must run the SAME precision mode, else the pair refuses rather than silently mixing roundings. THE LAUNCH is the incumbent kernel unchanged with the channel count hard-set to two, verbatim (mmvf.cu:930-931, the F32 arm; F16/BF16 twins :934-939): `mul_mat_vec_f_cuda((const float *) a->data, src1_d, nullptr, fusion, dst_d, ne00, ne01, 1, s01, s11, s1,` / `2, 2, 2, dx / (int64_t) ts, 0, dd / (int64_t) sizeof(float), 1, 1, s03, s13, s3, 0, prec, ctx.stream());` — channels {2,2,2}, weight channel stride dx/ts, ACTIVATION channel stride 0 (the broadcast), output channel stride dd/4, no bias, no fusion args. Bit-exactness is BY TEMPLATE IDENTITY, not by re-derivation: every output row executes the same kernel instantiation with the same block size it would have run alone. THE MATCHER half adds the graph-shape conditions (ggml-cuda.cu:4176ff): both nodes MUL_MAT; NEITHER carries the Hadamard hint (`ggml_get_op_params_i32(mm, 1) == GGML_HINT_SRC0_IS_HADAMARD` refuses — the deeper fwht-q8 quantizing fusion owns hinted matmuls, the same inter-fusion priority law the look-ahead rule pins); neither weight sits in a COMPUTE-usage buffer; both must pass the vector-kernel admission (ggml_cuda_should_use_mmvf — the dispatch-kind conjunct, the corpus's B280 rider already owns the thin-weight arm of THAT predicate: 'the 32-row GDN ssm_alpha/ssm_beta projections'); consecutive with view/noop nodes skippable between; the pairing identity gates verbatim: `mm1->src[1] != mm0->src[1] || mm1->src[0] == mm0 || mm1->src[1] == mm0` (same activation pointer; not the same weight; neither product's operand IS the other product); THE PRIORITY YIELD to deeper fusions, verbatim (ggml-cuda.cu:4197): '// leave a pair whose second product starts another fusion (bias add, GLU) to that fusion' — a following ADD or GLU node makes the pair stand aside; full aliasing refusal (each output against all inputs, and the two outputs against each other); the concurrent-stream gate; the dispatch site rides the SAME fusion flag and NVIDIA gate as the conv-chain rule (ggml-cuda.cu:5136-5139), returning the consumed node count so the loop skips the second mat-vec. TESTS are whole-graph with both products checked (test-backend-ops.cpp:4219-4220, verbatim: 'Two mat-vecs of one activation with same-shape float weights (the GDN alpha and beta projections); the CUDA backend' / 'can run them as one launch (GGML_CUDA_GDN_FUSION=1). Both products are checked.') across all three weight types × three geometries (:10074-10076: `(t, 1024, 8)`, `(t, 3072, 24)`, `(t, 130, 3)` for t in {F32, F16, BF16} — including a non-power-of-two, non-multiple K). ENV ARC: opt-in at #383 (shared flag), default-on at #398 — verbatim (ggml-cuda.cu:4223 at #398): 'the fused GDN op consumes raw) as one launch (on by default, GGML_CUDA_GDN_FUSION=0 disables it). Returns the' — the flag flip is the conv-chain rule's flip; both fusions demote with one switch. MEASURED (source-reported, H200 — provenance): #383 'decode +5-10% (2B to 27B)… with 90-240 fewer kernels per token' (the pair contributes one launch saved per layer-token to that total); #398 '9B decode +7.9% (353 -> 381 tok/s), 27B about +7.5%'. DECISION CONTENT: (a) two independent same-shape/same-stride/same-dtype mat-vecs sharing ONE activation POINTER may share one launch of the existing kernel — the second weight addressed as first + byte-offset via the channel axis, the activation broadcast at channel stride 0, NO weight stacking or concat required (the pair works on arbitrary allocations whose relative distance satisfies the alignment/nonzero/int-range gate); (b) exactly TWO products — the channel count is hardcoded 2, no N-way generalization is admitted by this evidence; (c) bit identity holds because every row runs the same template instance with the same block size as a solo launch — never by tolerance; (d) the yield laws are load-bearing: hinted matmuls and COMPUTE-buffer weights belong to the deeper quantizing fusion, and a pair whose second product feeds an ADD/GLU fusion is left to it — a fusion ladder is a priority order, never two racing peepholes; (e) the two outputs must agree on precision mode; (f) the demote switch is the shared GGML_CUDA_GDN_FUSION=0. CLASS SIGNATURE: a decode-shaped graph with consecutive single-output mat-vecs over one activation (sibling gate projections), the incumbent vector-kernel admission already true for both. REGIME: alpha/beta-style gate pairs; any adjacent same-activation projection pair whose weights happen to be same-shaped. ANTI-REGIME: different dtypes, shapes or strides (the pair launcher refuses); column counts > 1 per product (dst ne[1] != 1 refuses — that is the multi-column kernel's territory, not the pair's); an N-way fan (no evidence); a second product consumed by an activation/bias fusion (the yield); hinted or COMPUTE-buffer weights (the deeper fusion's nodes); aliased or overlapping weights/outputs (dx == 0 / dd == 0 / range overlap refuse). KINSHIP (do not double-count): the same-input family — fuse-gate-up-gemv-activation (entries_gpu_01, B58 + its B251/B276/B287 riders) owns the ARITHMETIC fusion of two sibling GEMVs PLUS a multiplicative activation epilogue; stacked-gate-up-single-launch-split-store (entries_gpu_106, B251) owns the LAYOUT-carried form (weights stacked back-to-back at load — a real layout requirement); same-input-gemv-weight-concat-at-upload (B63, cited from entries_gpu_08) owns concat-at-upload; same-input-gemv-segments-single-launch (entries_gpu_07, B58) owns the segment-table form. THIS owns the OFFSET-ARITHMETIC form: no layout change, no stacking, the pair exists purely in launch arguments — the family's layout-free member. cross-lane-column-packed-projections (entries_gpu_08) is the axis-transposed member (N inputs over one weight; this is two weights over one input). gqa-zero-stride-batch-broadcast (B197) is the stride-0-BROADCAST kin at the GEMM batch axis — same trick (a zero stride replicates an operand), different surface; cite, never merge. shape-kind-dispatch's B280 rider (entries_popcorn) owns the mmvf THIN-WEIGHT dispatch admission naming these very ssm_alpha/ssm_beta projections — the single mat-vec kind; THIS owns the pair LAUNCH over two admitted kinds; compose. sibling-kernel-admission-gap-absorbed-by-generalist (entries_gpu_75, B205) owns the MMVF-vs-MMF admission-gap law — dispatch admission, not pairing. The yield law's family owner is the exemplar (look-ahead-fusion-precomputed-skip-overlap-walk, B283: the deeper fusion wins shared nodes) — cite it for the ladder law alongside the hint/COMPUTE exclusions here. GREP EVIDENCE: 'paired|pair.?launch|mat-vec pair' → paired-A/B and paired-PCIe senses only (gpu_118, bench language) — no pair-LAUNCH owner; 'single.?column|one.?column' → fewrow band senses (gpu_66) — no single-column pair owner; 'mmvf|mul_mat_vec_f' → THREE hits (gpu_75 admission-gap, entries_popcorn B280 thin-admission rider, gpu_127's channel-uniform quote) — none an owner of the pair; 'channel.?stride' → gpu_49's activation-plane 'column stride' (different axis); 'broadcast' → the reduction/GEMM-batch senses — the activation-broadcast-across-weights pair form is unowned. NotBenchable here (llama.cpp CUDA kernel-dispatch sources; no CUDA validator in this corpus — the admission conjunction, the offset gate and the template-identity argument are CPU-testable and ARE the fixtures; the H200 figures are source-reported provenance, foreign silicon). Source: PrismML/llama.cpp commit 97ea5aeee1 (#383, bri-prism, 2026-10-24, MIT lineage) + commit bf8c069fde (#398, default-on flip) — ggml/src/ggml-cuda/mmvf.cu:884-941 + mmvf.cuh:15-17 (the pair launcher), ggml-cuda.cu:4173-4227 (the matcher) + :5136-5139 (dispatch), tests/test-backend-ops.cpp:4219-4233 + :10074-10076. Batch 295 / Plan 300 / Research 333.".to_string(),
            ref_shape: "// ref_shape: two consecutive single-column mat-vecs over one\n// activation — two launches of the same vector kernel, the activation\n// read twice.\n#![allow(dead_code)]\n\nfn mat_vec(w: &[f32], x: &[f32], rows: usize) -> Vec<f32> {\n    let mut out = vec![0.0; rows];\n    for r in 0..rows {\n        let mut s = 0.0f32;\n        for (wr, xr) in w[r * x.len()..(r + 1) * x.len()].iter().zip(x) {\n            s += wr * xr;\n        }\n        out[r] = s;\n    }\n    out\n}\n\n/// the naive decode step: two sibling gate projections, two launches\nfn gates_naive(w_alpha: &[f32], w_beta: &[f32], x: &[f32], rows: usize) -> (Vec<f32>, Vec<f32>, u32) {\n    let a = mat_vec(w_alpha, x, rows); // launch 1\n    let b = mat_vec(w_beta, x, rows);  // launch 2: same x, re-read\n    (a, b, 2)\n}\n\n#[test]\nfn two_launches_for_two_gate_projections() {\n    let x = [0.5f32, -1.0, 2.0];\n    let (a, b, launches) = gates_naive(&[1.0; 9], &[0.5; 9], &x, 3);\n    assert_eq!(launches, 2);\n    assert_eq!(a.len(), 3);\n    let _ = b;\n}\n".to_string(),
            opt_pattern: "// opt_pattern: ONE launch of the SAME kernel with channel count 2 —\n// the second weight addressed as first + byte offset (the channel\n// stride), the shared activation broadcast at channel stride 0. The\n// matcher is a conjunctive gate; any miss launches the incumbent pair.\n#![allow(dead_code)]\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum WType { F32, F16, Bf16 }\n\n#[derive(Clone)]\nstruct Mv {\n    weight: (usize, usize), // (offset, len) in the arena\n    wtype: WType,\n    activation: usize,      // arena offset of the shared input\n    out: (usize, usize),    // (offset, len)\n    hinted: bool,           // the deeper quantizing fusion's hint\n    compute_buffer: bool,\n    vector_kernel_admitted: bool,\n    prec: u8,\n}\n\nfn range_overlaps(a: (usize, usize), b: (usize, usize)) -> bool {\n    a.0 < a.0 + a.1 && b.0 < b.0 + b.1 && a.0 < b.0 + b.1 && b.0 < a.0 + a.1\n}\n\nfn elem_size(t: WType) -> usize {\n    match t { WType::F32 => 4, WType::F16 | WType::Bf16 => 2 }\n}\n\n/// the launcher-level gate (the mmvf half): same activation pointer, same\n/// weight type/shape/strides, single-column f32 outputs, offsets\n/// nonzero / element-aligned / int-representable, precision equal.\nfn pair_qualifies(a: &Mv, b: &Mv, single_column_out: bool) -> bool {\n    a.wtype == b.wtype\n        && a.activation == b.activation\n        && a.weight.1 == b.weight.1\n        && single_column_out\n        && !a.hinted\n        && !b.hinted\n        && !a.compute_buffer\n        && !b.compute_buffer\n        && a.vector_kernel_admitted\n        && b.vector_kernel_admitted\n        && a.prec == b.prec\n        && a.weight.0 != b.weight.0 // dx == 0 refuses\n        && a.out.0 != b.out.0       // dd == 0 refuses\n}\n\nstruct Arena(Vec<u8>);\n\n/// the launcher: ONE kernel call, channels = 2, weight channel stride\n/// = dx / elem_size, activation channel stride = 0, dst channel stride\n/// = dd / 4. Every row runs the same template instance + block size as\n/// a solo launch, so both products are bit-identical to the pair.\nfn pair_launch(arena: &Arena, a: &Mv, b: &Mv) -> Option<(Vec<f32>, Vec<f32>)> {\n    let ts = elem_size(a.wtype);\n    let dx = b.weight.0 as i64 - a.weight.0 as i64;\n    let dd = b.out.0 as i64 - a.out.0 as i64;\n    if dx % ts as i64 != 0 || dd % 4 != 0 { return None; }\n    if dx.abs() / ts as i64 > i32::MAX as i64 { return None; }\n    let _ = dd; // the dst stride the real launcher passes through\n    let k = 9usize; // fixture geometry: k = 9 per row\n    let x: [f32; 9] = [0.5, -1.0, 2.0, 0.25, -0.5, 1.5, 0.75, -0.25, 1.0];\n    let rows = a.weight.1 / k;\n    let read_row = |base: usize, r: usize| -> f32 {\n        let mut s = 0.0f32;\n        for kk in 0..k {\n            s += arena.0[base + r * k * ts + kk * ts] as f32 * x[kk];\n        }\n        s\n    };\n    let mut va = vec![0.0f32; rows];\n    let mut vb = vec![0.0f32; rows];\n    for r in 0..rows {\n        va[r] = read_row(a.weight.0, r); // channel 0\n        vb[r] = read_row((a.weight.0 as i64 + dx) as usize, r); // channel 1: the SAME row walk shifted by dx\n    }\n    Some((va, vb)) // ONE launch produced both\n}\n\n#[test]\nfn the_pair_fires_and_produces_both_columns_in_one_launch() {\n    let mut bytes = vec![0u8; 4096];\n    for (i, b) in bytes.iter_mut().enumerate() { *b = (i % 5 + 1) as u8; }\n    let arena = Arena(bytes);\n    let a = Mv { weight: (0, 27), wtype: WType::F32, activation: 900, out: (1500, 12),\n                 hinted: false, compute_buffer: false, vector_kernel_admitted: true, prec: 0 };\n    let mut b = a.clone();\n    b.weight = (108, 27); // same shape/strides, 27 f32 later — dx = 108, aligned\n    b.out = (1600, 12);\n    assert!(pair_qualifies(&a, &b, true));\n    assert!(!range_overlaps(a.out, b.out));\n    let (va, vb) = pair_launch(&arena, &a, &b).expect(\"qualifying pair launches\");\n    assert_eq!(va.len(), 3);\n    assert_eq!(vb.len(), 3);\n    // channel 1's walk is channel 0's walk shifted by dx — same template,\n    // same order per row: bit-identity by construction, not tolerance\n    assert_ne!(va, vb);\n}\n\n#[test]\nfn every_refusal_arm_names_its_conjunct() {\n    let a = Mv { weight: (0, 27), wtype: WType::F32, activation: 900, out: (1500, 12),\n                 hinted: false, compute_buffer: false, vector_kernel_admitted: true, prec: 0 };\n    // same weight twice: dx == 0\n    let same = a.clone();\n    assert!(!pair_qualifies(&a, &same, true));\n    // hinted weight: the deeper quantizing fusion owns it\n    let mut hinted = a.clone();\n    hinted.weight = (108, 27);\n    hinted.hinted = true;\n    assert!(!pair_qualifies(&a, &hinted, true));\n    // precision mismatch\n    let mut prec = a.clone();\n    prec.weight = (108, 27);\n    prec.prec = 1;\n    assert!(!pair_qualifies(&a, &prec, true));\n    // multi-column outputs: the pair form is single-column only\n    let mut wide = a.clone();\n    wide.weight = (108, 27);\n    assert!(!pair_qualifies(&a, &wide, false));\n}\n".to_string(),
        },
    ]
}

pub fn entries() -> Vec<KernelRule> {
    let mut v = Vec::new();
    v.extend(slice_conv_chain());
    v.extend(slice_fwht_rows());
    v.extend(slice_graph_replay());
    v
}

#[allow(clippy::too_many_lines)]
fn slice_fwht_rows() -> Vec<KernelRule> {
    vec![
        // ── Rule 3 (category B — launch geometry, the block-thread-width
        // admission of a fixed-grid kernel family): #396. The block width
        // of a ONE-BLOCK-PER-TRANSFORM kernel family is admitted by the
        // number of transforms in flight — the grid's block count — not
        // fixed at the family's historical constant; bit-identical because
        // the butterfly's stage order is thread-count-independent. ──
        KernelRule {
            rule_id: "in-flight-transform-count-admits-block-thread-width".to_string(),
            gpu_concept: "MECHANISM (the block-thread width of a ONE-BLOCK-PER-TRANSFORM kernel family is admitted by the number of transforms in flight — the grid's block count — not fixed at the family's historical constant; category B — launch geometry): a one-block-per-row kernel family picks its thread width once, for the wide-grid posture it was tuned in, and then ships that width everywhere — including the decode and speculative-verify postures where the grid collapses to a handful of blocks and each block's fixed thread count strands most of an SM's slot table. The repair is a launch-time admission on the GRID axis: few transforms in flight widen the block (up to the hardware ceiling, floored so each thread keeps a minimum pair of elements); many transforms in flight keep the incumbent narrow width, because a full grid already fills the machine and wider blocks would only cut resident-blocks-per-SM. The PrismML instance, verbatim (fwht.cuh:62-66, the + side at ef119d136e): 'Threads per block for the one-block-per-transform FWHT kernels (fwht_cuda_block, fwht_quantize_q8_1) at width n. / 256 by default; with few transforms in flight (decode and speculative verify: 64 or fewer) min(n/2, 1024), so each / thread keeps at least two elements and the few blocks there are use more of the SM. The butterfly runs its stages / in the same order for any block width, so the result is bit-identical. GGML_CUDA_FWHT_NT overrides the wide value / (256 disables it).' THE ADMISSION IS CONJUNCTIVE, every term load-bearing, verbatim (fwht.cuh:67-74): `static inline int ggml_cuda_fwht_block_threads(const int n, const int64_t n_transforms) {` / `static const int wide_override = getenv(\"GGML_CUDA_FWHT_NT\") ? atoi(getenv(\"GGML_CUDA_FWHT_NT\")) : 0;` / `if (n_transforms > 64 || n < 512) {` / `return 256;` / `}` / `const int nt = wide_override > 0 ? wide_override : (n/2 < 1024 ? n/2 : 1024);` / `return (nt == 512 || nt == 1024) && nt <= n ? nt : 256;` / `}`. The four terms: (1) THE ROWS GATE — `n_transforms > 64` keeps the incumbent; 64 is the decode/verify grid scale, the posture where 'the few blocks there are' cannot fill the SMs (the family's own prior motivation, fwht.cu:206: 'From 512 up, one block of FWHT_BLOCK_THREADS per row (fwht_cuda_block).' — the block form won the width axis; this commit admits its thread axis by the grid it actually launches); (2) THE WIDTH FLOOR — `n < 512` keeps 256 (below the floor the n/2 candidate is not wider than the incumbent; the width ladder owns those rungs); (3) THE CANONICAL-WIDTH CHECK — `nt == 512 || nt == 1024` plus `nt <= n`: the wide form engages only where min(n/2, 1024) lands on a compiled template width, i.e. n = 1024 → 512 threads, n ≥ 2048 → 1024 threads; n = 512 computes nt = 256 and falls through — the admission never invents a width the kernel family did not compile; (4) THE ENV OVERRIDE — GGML_CUDA_FWHT_NT replaces the derived value ('256 disables it' — any value outside {512, 1024} falls back to the incumbent, so the demote path is the same code as the refuse path). THE GRID AXIS IS THE LAUNCH GEOMETRY: the block kernel's grid IS the in-flight transform count — verbatim (fwht.cu:221, inside the FWHT_BLOCK_LAUNCH macro the commit converts to a parameterized-width form): `const dim3 g((unsigned) rows, 1, 1), b(NTT, 1, 1);` — one block per row, so `rows` is simultaneously the block count and the admission input, read at the launch site (fwht.cu:230): `const int nt = ggml_cuda_fwht_block_threads(n, rows);`. The dispatch stays a compile-time ladder so no runtime-compiled variant is minted, verbatim (fwht.cu:233-239): `if constexpr (NN >= 1024) {` / `if (nt == 1024) FWHT_BLOCK_LAUNCH(NN, 1024)` / `}` / `if constexpr (NN >= 512) {` / `if (nt == 512) FWHT_BLOCK_LAUNCH(NN, 512)` / `}` / `FWHT_BLOCK_LAUNCH(NN, FWHT_BLOCK_THREADS)` — each template width is a `case` whose body compiles its two wide arms only when the template admits them (`constexpr`), falling through to the incumbent width arm; the shipped launch set stays {512, 1024, 2048, 4096, 8192} × {256, 512, 1024} with the wide arms dead code where NN is too small. THE SECOND KERNEL SHARES THE ONE ADMISSION — the fused transform+quantize writer routes through the same helper so the two consumers cannot drift, verbatim (quantize.cu:308-309): '// wider blocks for few rows (decode / verify), same choice as fwht_cuda_block' / `const int nt = ggml_cuda_fwht_block_threads(N, ne1*ne2*ne3);` — the quantize kernel's in-flight transform count is the batch-row product `ne1*ne2*ne3` (its grid, quantize.cu:286-287: `const dim3 num_blocks((unsigned) (ne0 / N), (unsigned) ne1, (unsigned) (ne2*ne3));` / `const dim3 block_size(NT, 1, 1);`), and its incumbent width became the template default of the newly-split launch shim, verbatim (quantize.cu:322): `fwht_quantize_launch_nt<N, (N < 256 ? N : 256), T>(x, signs, vy, layout, ne00, ne0, ne1, ne2, ne3, scale, stream);` — the old in-body `constexpr int NT` moves into the template parameter so the wide arms are the same instantiated kernel at a different NT, never a second transcription. BIT IDENTITY IS AN ORDERING CLAIM, not a tolerance claim: the butterfly's per-element arithmetic is unchanged and its stage order is thread-count-independent — verbatim, the commit message: 'the butterfly stage order does not depend on the thread count, so results are bit-identical' and the header's own law (fwht.cuh:64-65): 'The butterfly runs its stages / in the same order for any block width, so the result is bit-identical.' Widening NT re-stripes WHICH thread holds which element (NE = N/NT per thread, floored at 2 by the `nt <= n/2` shape — 'so each / thread keeps at least two elements'), which re-homes stages between the in-register and cross-thread tiers; that re-homing is identity-neutral because each stage is the same add/subtract whichever tier runs it — the family law the corpus already carries from the Batch-288 block-diagonal rider on fwht-wide-block-row-per-threadgroup-exchange-ladder ('Each stage is the same add/subtract whichever level runs it, so a segment's result is bit-identical to a width-blk transform.'). The per-thread element count must stay ≥ 2 so the top register tier keeps intra-thread pairs to walk. Verification is token-level ('Tokens identical.'), and the shape floor is the same static-assert family the upstream ladder carries (`NE >= 1 && N % NT == 0 && NT % warp_size == 0` — B211's shape discipline; 512 and 1024 satisfy it for every compiled N). REGIME: one-block-per-work-item kernel families whose grid collapses at serving latencies (decode, speculative verify: tens of blocks) where the machine has thousands of resident-block slots; any width-parameterized kernel whose bit-identity argument is stage-order (deterministic exchange order) rather than reduction-order-sensitive (a reassociation would need the tolerance walk — this is not that); postures where the SAME width serves both a full prefill grid and a near-empty decode grid. ANTI-REGIME: many-block grids (rows > 64 here) — the machine is full, wider blocks only cut resident-blocks-per-SM and load balance; widths whose min(n/2, ceiling) is not a compiled variant (the admission must refuse, never clamp to an uncompiled NT); kernels whose correctness depends on a specific elements-per-thread count (this family's floor is 2; a kernel needing more must raise the floor term, not drop the rule); reduction trees whose order moves with the striping (those are the reassociation class — tolerance walk, different rule). KINSHIP (do not double-count): fwht-wide-block-row-per-threadgroup-exchange-ladder (entries_gpu_27, B116 + riders B176/B180/B192/B199/B211/B251/B288) owns the WIDTH axis — which kernel form (warp / block / smem) serves which transform width N, with the gate-shape history across vendors; ITS Batch-251 rider pinned the fixed-width premise this commit replaces ('one block of FWHT_BLOCK_THREADS per row', FWHT_BLOCK_THREADS 256, fwht.cu:135 at the pin) — cite for the family and the width axis; THIS owns the block's THREAD axis admitted by the grid's ROWS axis, a term no prior gate in the family carried (the tetherto B180 rider's `rows == 1 && cc >= BLACKWELL` term gated whether the BLOCK FORM engaged at n=512 — an engagement gate on the width axis, not a thread-width choice within the engaged form). fwht-butterfly-staging-ladder-warp-smem-register (entries_gpu_45, B166) owns span-classified stage placement at a fixed width — the substrate axis this commit's re-stripe moves stages across; the bit-identity law this rule cites (same add/subtract whichever tier) is that family's, but the ROWS admission is new. fwht-shuffle-xor-butterfly-register-resident (entries_gpu_11, B96) is the all-register pole below the width floor — this rule fires above it. row-dot-split-inner-axis-block-reduce (entries_gpu_06 + the Batch-108 capped-occupancy complement + the Batch-269 threadgroup-radius face) is the nearest launch-geometry kin: the same rows-too-few-for-the-machine trigger, but its lever SPLITS the reduction across lanes of NEW workgroups (grid expansion on a cooperative op); THIS widens the EXISTING one-block-per-row blocks at a FIXED grid (block expansion on a transform — no reduction to cooperate on, so the block cannot split the way a reduction can). wide-row-copy-tile-rows-across-workgroups (entries_gpu_11, B96) + its Batch-192 contrast rider own the widening-axis taxonomy for streaming vs exchange ops — this rule is a third entry: an exchange network keeping one block per row and widening the block's thread count (elements-per-thread DOWN toward the pair floor), the opposite direction of argsort's columns-per-thread widening, motivated by occupancy rather than register pressure. reduction-restructure-needs-source-owned-comparator (entries_gpu_09, B95) owns the bit-identity oracle axis — compose: any port of this admission to a reduction-bearing kernel needs that rule's comparator, this rule's stage-order argument suffices for exchange networks. GREP EVIDENCE (over the corpus): 'fwht' → the family rules named above, none carries a rows→thread-width term; 'wider.{0,20}block' → hits land in wide-row-copy-tile-rows-across-workgroups and its rider (the row-streaming/argsort family — other families, the staged row's claim VERIFIED); 'in.flight|undersubscription' → zero owners; 'block.width|thread.count|threadgroup size' → the staged-ladder and tile-loading geometry families, none admits by grid block count; 'min(n' → zero. No owner of the in-flight-transform-count → block-thread-width admission. NotBenchable here (llama.cpp CUDA launch-geometry sources; the corpus serves no CUDA validator — the admission arithmetic, the constexpr ladder and the stage-order identity are CPU-testable and ARE the fixtures; the H200 figures are source-reported provenance and the commit is NOT in the scored tag prism-b10819-909f0ca, so no our-box datum exists — league re-cell pending). MEASURED (source-reported, H200 — provenance, never bars), verbatim from the commit body: 'On H200: 9B +2.6-2.9% (no speculation), MTP3 +2.5-3.0%, DFlash7 +4.3-4.9%; 27B MTP2 +4.0-4.4%. Tokens identical.' STAGED-ROW DRIFT: the staging summary '+2.6-4.9% 9B, +4% 27B MTP' pools three DIFFERENT 9B-family rows into one range — the 4.9% endpoint is DFlash7 (+4.3-4.9%), not plain 9B decode (+2.6-2.9%); and MTP3's lower bound (+2.5%) sits BELOW the staging floor (+2.6%). The 27B '+4%' is honest (+4.0-4.4% MTP2). Quote the per-row figures, never the pooled range. DECISION CONTENT: (a) the admission input is the GRID's block count (transforms in flight), read at the launch site, never the problem's row count in the abstract — the same kernel launches 256-wide at prefill and 1024-wide at decode; (b) the wide width is min(n/2, hardware ceiling) filtered through the compiled template set — the admission never invents a variant; (c) the pair floor (each thread ≥ 2 elements) is the shape invariant that keeps the top tier non-empty; (d) bit identity = stage-order invariance + per-element expression invariance, verified at token level, never a tolerance band; (e) ONE shared admission helper feeding every kernel of the family (the transform kernel and the fused quantize writer cannot drift); (f) the env override replaces the derived value and 256 disables — the demote path is the refuse path. CLASS SIGNATURE: a one-block-per-work-item kernel with a width-templated body; a grid whose block count varies by orders of magnitude across serving postures; a butterfly/exchange whose stage order is thread-count-independent. Source: PrismML/llama.cpp commit ef119d136e (#396, bri-prism, 2026-10-24, MIT lineage) — ggml/src/ggml-cuda/fwht.cuh:62-74 (the admission helper + its law comment), fwht.cu:135 (FWHT_BLOCK_THREADS 256), :220-240 (the parameterized launch macro + the constexpr ladder), quantize.cu:280-323 (the NT-templated launch shim + the shared admission). Batch 295 / Plan 300 / Research 333.".to_string(),
            ref_shape: "// ref_shape: one thread-width for every posture — the wide-grid\n// constant shipped to the near-empty decode grid. rows = transforms\n// in flight = the grid's block count (one block per row).\n#![allow(dead_code)]\n\nconst NT: usize = 256; // the family's historical constant, chosen at prefill\nconst N: usize = 2048;\n\nfn fwht_block<const NN: usize, const NTT: usize>(blocks: u32, x: &[f32], out: &mut [f32]) {\n    // the transform body is the family's — the launch shape is the rule\n    let _ = (blocks, x, out);\n}\n\nfn launch(rows: usize, x: &[f32], out: &mut [f32]) {\n    // 8 blocks x 256 threads = 2048 threads in flight on a GPU with\n    // tens of thousands of resident slots: every SM but a few idles,\n    // and each thread serially walks N/NT = 8 elements.\n    let blocks = rows as u32;\n    fwht_block::<N, NT>(blocks, x, out);\n}\n\n#[test]\nfn the_decode_grid_ships_the_prefill_width() {\n    let mut out = vec![0.0f32; N];\n    let x: Vec<f32> = (0..N).map(|i| (i % 7) as f32).collect();\n    launch(8, &x, &mut out); // decode: 8 blocks, 256-wide each\n    let _ = out;\n}\n".to_string(),
            opt_pattern: "// opt_pattern: the block width is admitted by the grid's block\n// count. Few transforms in flight widen the block so each block uses\n// more of the SM; the stage order is thread-count-independent, so bits\n// match. Canonical widths only — the admission never invents a variant.\n#![allow(dead_code)]\n\nconst N: usize = 2048;\nconst ENV_NT: usize = 0; // GGML_CUDA_FWHT_NT; 256 disables the wide form\n\nfn fwht_block<const NN: usize, const NTT: usize>(blocks: u32, x: &[f32], out: &mut [f32]) {\n    let _ = (blocks, x, out); // the transform body is the family's\n}\n\nconst fn block_threads(n: usize, rows: usize, env_override: usize) -> usize {\n    if rows > 64 || n < 512 {\n        return 256; // full grid or below the width floor: the incumbent\n    }\n    let half = n / 2;\n    let want = if env_override > 0 {\n        env_override\n    } else if half < 1024 {\n        half\n    } else {\n        1024\n    };\n    // canonical widths only: never invent an uncompiled variant\n    if (want == 512 || want == 1024) && want <= n { want } else { 256 }\n}\n\nfn launch(rows: usize, x: &[f32], out: &mut [f32]) {\n    let nt = block_threads(N, rows, ENV_NT); // rows == grid.x == blocks\n    match nt {\n        // each arm a compiled template; the pair floor NE = N/NT >= 2\n        1024 => fwht_block::<N, 1024>(rows as u32, x, out),\n        512 => fwht_block::<N, 512>(rows as u32, x, out),\n        _ => fwht_block::<N, 256>(rows as u32, x, out),\n    }\n}\n\n#[test]\nfn decode_widens_and_prefill_keeps_the_incumbent() {\n    let mut out = vec![0.0f32; N];\n    let x: Vec<f32> = (0..N).map(|i| (i % 7) as f32).collect();\n    // decode (rows = 8, n = 2048): min(n/2, 1024) = 1024 — canonical.\n    assert_eq!(block_threads(N, 8, 0), 1024);\n    launch(8, &x, &mut out);\n    // prefill (rows = 512 > 64): the incumbent, unchanged.\n    assert_eq!(block_threads(N, 512, 0), 256);\n    launch(512, &x, &mut out);\n    // n = 512 computes nt = 256 and falls through — never invents a width.\n    assert_eq!(block_threads(512, 8, 0), 256);\n    // the env override replaces the derived value; 256 disables.\n    assert_eq!(block_threads(N, 8, 512), 512);\n    assert_eq!(block_threads(N, 8, 256), 256);\n    assert_eq!(block_threads(N, 8, 777), 256); // non-canonical: refuse\n}\n".to_string(),
        },
    ]
}

#[allow(clippy::too_many_lines)]
fn slice_graph_replay() -> Vec<KernelRule> {
    vec![
        // ── Rule 4 (category D — dispatch/scheduling, host-side
        // graph-evaluation path): #393 face (b). Replay visits no nodes, so
        // every node scan a replay cannot read is dead host work: the
        // compatibility verdict is memoized on a post-proof uid token, and
        // the consumer-count map is built only in the postures whose code
        // reads it. Face (a) — the batched sched input uploads — is ALREADY
        // corpus (the Batch-283 rider on chain-dispatches-single-sync-point,
        // entries_gpu_01, same sha). ──
        KernelRule {
            rule_id: "graph-replay-skips-host-node-scans".to_string(),
            gpu_concept: "MECHANISM (host-side per-node work must be gated on the evaluator path that actually runs — replay visits no nodes, so every node scan a replay cannot read is dead host work; and a validation verdict already proven for an unchanged graph object is memoized on a post-proof identity token instead of re-derived; category D — dispatch/scheduling, host-side graph-evaluation path): a CUDA-graph evaluator runs THREE postures per call — eager evaluation (nodes visited), capture or re-capture (nodes visited while recorded), and replay (nodes NOT visited; the captured exec launches). Host-side preprocessing that scans the node list — compatibility checks, consumer-count maps, property tables — is mandatory in the first two and DEAD in the third; the naive path re-runs all of it every call because the postures share one entry point. The PrismML instance lands TWO gates, verbatim from the commit message: 'On the CUDA side, host only: skip the graph compatibility scan on replay when the graph uid is unchanged, and build the shared-Q8 consumer map only while nodes are evaluated or captured.' — and the whole change is host-side decision work: 'Logits and server responses are byte-identical.' GATE 1 — THE COMPATIBILITY SCAN IS MEMOIZED ON THE POST-PROOF UID TOKEN. The naive line ran a full node scan every call to decide whether the graph may be captured at all; the replacement short-circuits on a token minted only after a previous proof, verbatim (ggml-cuda.cu:5749-5751, + side): '// graph->uid is only set for a compatible graph (ggml_cuda_graph_update_required), and an unchanged uid means' / '// the same nodes: skip the scan of the nodes' / `const bool graph_compatible = (cgraph->uid != 0 && cgraph->uid == graph->uid) || ggml_cuda_graph_check_compability(cgraph);`. THE SAFETY ARGUMENT IS A MINTING-CONDITION AUDIT, not a hash-collision argument: `cgraph->uid` is a monotone per-graph-object identity (ggml_graph_next_uid, ggml.c:56; uids start at 1, 0 is the never-assigned sentinel), and `graph->uid` is assigned inside `ggml_cuda_graph_update_required` (ggml-cuda.cu:2733, pre-existing context: 'graph->uid = cgraph->uid;') — a function reached ONLY under `graph_compatible` (it sits inside the compatible branch). So `graph->uid == X` certifies: some cgraph with uid X previously PASSED the compatibility scan; uid equality identifies the SAME graph object; the same object's node list is immutable after build; and `ggml_cuda_graph_check_compability` is a pure function of that list plus the device (its whole body, pre-existing context at ggml-cuda.cu:2672-2703: a loop 'for (int i = 0; i < cgraph->n_nodes; i++)' checking view-or-noop and the mul_mat_id sync-needs arm). Therefore a match implies the scan's answer, and re-running it re-derives a known constant. The skipped scan is a FULL node walk — the cost this gate removes is O(n_nodes) host time per decode step on the replay path, exactly the class the commit prices ('Cut about 55-65 us of host time per decode step (about 130 us on 27B)'). THE INVALIDATION LADDER — every way the memo must miss, each forced back to the full scan: (1) `cgraph->uid == 0` (a graph built without a uid, or the sentinel) cannot hit; (2) `cgraph->uid != graph->uid` — a rebuilt graph object or two objects alternating on one cache slot — mismatches and re-scans, then re-mints `graph->uid` at :2733; (3) the graph key itself (pre-existing, ggml-cuda.cu:2709-2718) already mixes the first node's shape and the node count into the cache key (the corpus's Batch-274 #378 rider law), so the uid compare happens only within one shape-class bucket; (4) downstream, `ggml_cuda_graph_update_required` returning true (properties changed) resets warmup and forces the eager path until stable — re-scans on every one of those calls. GATE 2 — THE CONSUMER-COUNT MAP IS BUILT ONLY WHERE ITS READERS RUN. The shared-Q8 fusion dispatch consults a per-src1 consumer-count map built by a second full node scan; its readers live exclusively inside the evaluate-or-capture pass, so the build is guarded to exactly the union of the paths that read it, verbatim (ggml-cuda.cu:5334-5343, + side): '// only read while the nodes are evaluated or captured: not built when a captured CUDA graph is replayed' / `std::map<const ggml_tensor *, std::array<int, GGML_TYPE_COUNT>> gb10_shared_q8_consumer_counts;` / `if (!use_cuda_graph || cuda_graph_update_required) {` / `for (int j = 0; j < cgraph->n_nodes; ++j) {` / `const ggml_tensor * candidate = cgraph->nodes[j];` / `if (candidate->op == GGML_OP_MUL_MAT && candidate->src[0] && candidate->src[1]) {` / `++gb10_shared_q8_consumer_counts[candidate->src[1]][candidate->src[0]->type];` / `}` / `}` / `}`. The reader is a lookup lambda (ggml-cuda.cu:5344-5347, verbatim): `const auto gb10_shared_q8_consumer_count = [&](const ggml_tensor * src1, ggml_type type) {` / `const auto it = gb10_shared_q8_consumer_counts.find(src1);` / `return it == gb10_shared_q8_consumer_counts.end() ? 0 : it->second[type];` / `};` — and the guard's two disjuncts are precisely the visiting postures: `!use_cuda_graph` (eager) or `cuda_graph_update_required` (capture/re-capture). On replay both are false, no node is visited, the lambda is never called, and the map is an empty declaration — zero heap, zero scan. THE SAFETY RESTS ON A READER AUDIT THE COMMENT RECORDS: the gate is sound IFF every consumer of the map sits on the node-visit path; the skip's failure mode (if a reader were missed) is a silent count-0 — a benign-direction degradation of the fusion decision, never a wrong result — but the audit is the rule's load-bearing obligation, and the in-code comment is its record. THE REPLAY-VS-CAPTURE DISTINCTION IS THE RULE'S SPINE: capture-time work must run (the capture bakes the exec; its decisions must be derived then), replay-time work must not (nothing host-side reads it). The pre-existing tree already skipped the per-node PROPERTY diff on uid match (ggml-cuda.cu:2726-2731, pre-existing from upstream #21764, verbatim: `if (cgraph->uid != 0 &&` / `cgraph->uid == graph->uid) {` / `GGML_LOG_DEBUG(\"CUDA Graph id %zu reused\\n\", cgraph->uid);` / `GGML_ASSERT((int)graph->node_props.size() == cgraph->n_nodes);` / `return false;` / `}`) — this commit extends the same token to the compatibility scan (which runs BEFORE update_required, so the property shortcut alone never reached it) and adds the map gate. CORPUS-LAW DRIFT FLAGGED AND RECONCILED: the Batch-274 rider on identity-keyed-graph-retention-stable-arena states 'a key hash COLLISION degrades to update-in-place, never to a wrong replay (the hash is an index, the node-walk is the proof)' — that law described the pre-#21764 tree; the current fork tree MINTS the token at the end of a validated cycle and skips both walks on match. The reconciled law: the proof is MEMOIZED, not skipped — the token is minted only after the check it vouches for actually ran, and the minting site is the token's authority. Any port must locate its own minting site and prove the minting condition, never assume equality-with-a-cached-hash is itself evidence. (The rider itself carries this annotation as of this batch.) REGIME: replay/capture-style evaluators whose host entry point is shared across eager/capture/replay postures; node-list scans consumed only by the node-visit path; validation predicates that are pure functions of an immutable per-identity structure, re-evaluated per call. ANTI-REGIME: postures where host-side per-node work feeds state the REPLAY consumes (a replay-time consumer of a capture-time map must force the build — gate the reader, not just the writer); identities that can be recycled while cached (the uid is monotone per object — a handle-recycling identity needs the destroy-epoch treatment, descriptor-set-binding-memo-destroy-epoch's law); validation predicates that read mutable state (the scan's answer may change without the uid changing — the minting condition must cover every input of the predicate; the device cc term here is fixed per context, which is why the purity holds). KINSHIP (do not double-count): graph-exec-update-gated-by-captured-topology-signature (entries_gpu_48, B178) owns the CAPTURED-graph signature axis for executable sharing/update across profiles — its key is derived from the capture itself; THIS consumes a construction-time per-object token and owns host-scan SKIPPING, not exec sharing. identity-keyed-graph-retention-stable-arena (entries_gpu_08 + the Batch-274 #378 key-composition rider) owns retention keys and the shape-mixed cache key this rule's compare presumes — cite for the key, own the scan-skip; the rider's authority-law drift is flagged and reconciled above. descriptor-set-binding-memo-destroy-epoch (entries_gpu_59, B192) is the memo-family spirit-kin: skip a redundant host-side API action on replay-style workloads keyed by identity compare, with an epoch-based invalidation for handle recycling — different object (Vulkan descriptor sets), different hazard, no node scan. captured-graph-bakes-buffer-addresses (entries_gpu_07) and capture-region-dispatch-only (entries_gpu_07) own the capture-side hazard/hygiene laws — adjacent, different axis. per-request-dirty-range-clear-graph-capture-sticky-marks (entries_gpu_105, B251 + the B265 lifecycle rider) owns capture-time state marks and graph-set lifecycle vs reclamation — different axis. shape-bucketed-graph-cache-lru (entries_gpu_57) owns the cache-finding axis. chain-dispatches-single-sync-point's Batch-283 rider (entries_gpu_01) owns this same commit's OTHER half (the scheduler upload batching) — sibling faces of one commit, never merged. GREP EVIDENCE (over the corpus): 'graph.{0,5}replay|replay' → the hits are the replay-hazard/replay-family rules named above (baked addresses, sticky marks, journaled rollback, descriptor memo) — none owns a replay-time scan skip; 'node scan|scan.{0,10}node|check_compability|compatibility scan' → zero owners; 'uid' → zero owners (the corpus's only epochs are the descriptor destroy-epoch and monotone arrival counters); 'graph-capture-sticky|captured-topology-signature' → exactly the two named anchors, both non-owners (capture-time / exec-sharing axes — adjudicated). The replay-time node-scan skip and the uid-memoized compatibility proof are both unowned. NotBenchable here (CUDA host-path decision work; the corpus serves no CUDA validator — the guard predicates, the minting-condition audit and the posture lattice are CPU-testable and ARE the fixtures; the µs figures are source-reported provenance; the commit IS in the scored tag prism-b10819-909f0ca, and the our-box Bench-1000 datum (+2.11% opponent decode, already recorded on the Batch-283 rider) prices the commit's WHOLE host-cut, not this gate separately — no independent our-box cell exists for face (b) alone). MEASURED (source-reported, H200 — provenance, never bars), verbatim from the commit body: 'Cut about 55-65 us of host time per decode step (about 130 us on 27B).' and 'On H200: decode +2-3.5% (2B-27B), server +2-4.4%, 9B MTP K=2 +2.9%.' STAGED-ROW CHECK: the staging note's '~55-65 µs/decode-step' matches the commit; the note OMITS the 27B ~130 µs figure — a supplement, not a drift. The µs band prices the commit's two CUDA gates PLUS the scheduler upload half together; it is not a per-gate figure and must never be quoted as one. DECISION CONTENT: (a) enumerate the evaluator's postures first (eager / capture / replay); a host-side node scan is admissible only in the postures that visit nodes — the guard is the exact disjunction of those postures; (b) a memoized validation verdict requires a MINTING-SITE audit: the token must be written only where the predicate has already been evaluated true for this identity, on an immutable predicate input set; (c) the sentinel arm (uid 0) and the mismatch arm route to the full scan — the memo's miss paths are the scan paths, never a refusal; (d) a skipped build whose readers are audited is byte-identical by construction — the audit comment is part of the artifact; (e) the skipped work is host-only: no device computation, capture content, or launch parameter may change. CLASS SIGNATURE: one shared evaluator entry point over an immutable node list with three execution postures; per-node host preprocessing consumed only under node visits; a monotone per-object identity token writable only after a validation pass. Source: PrismML/llama.cpp commit 63f16c408f (#393, bri-prism, 2026-10-24, MIT lineage) — ggml/src/ggml-cuda/ggml-cuda.cu:5334-5347 (the map gate + its reader lambda, + side), :5749-5751 (the compat-scan uid memo, + side); pre-existing context cited at the pin: :2672-2703 (ggml_cuda_graph_check_compability — the skipped scan), :2709-2718 (the shape-mixed graph key, #378), :2726-2733 (the uid mint + the property shortcut, upstream #21764), ggml/src/ggml.c:56 (ggml_graph_next_uid), ggml/src/ggml-impl.h (the uid field). Batch 295 / Plan 300 / Research 333.".to_string(),
            ref_shape: "// ref_shape: one entry point, and every host-side node scan runs on\n// EVERY call — including pure replays, where no node is ever visited.\n#![allow(dead_code)]\n\nuse std::collections::HashMap;\n\nconst NTYPES: usize = 4;\n\n#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]\nstruct NodeId(usize);\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Op { MulMat, View, Other }\n\nstruct Node {\n    op: Op,\n    ty: usize,\n    src1: Option<NodeId>,\n}\n\nstruct Graph {\n    nodes: Vec<Node>,\n}\n\ntype Counts = HashMap<NodeId, [u32; NTYPES]>;\n\n/// scan 1: is this graph capturable at all? a full node walk per call.\nfn check_compability(graph: &Graph) -> bool {\n    graph.nodes.iter().all(|n| match n.op {\n        Op::View | Op::Other => true,\n        Op::MulMat => n.src1.is_some(), // the sync-needs arm\n    })\n}\n\nfn run_or_capture(_graph: &Graph, _props_changed: bool, _counts: &Counts) {}\nfn run_eager(_graph: &Graph) {}\n\n/// the naive evaluator: three full node walks on EVERY call.\nfn evaluate(graph: &Graph, visiting: bool) {\n    // scan 1: re-derived per call, even on replay.\n    let compatible = check_compability(graph);\n    if compatible {\n        // scan 2: per-node property diff against the cached exec.\n        let props_changed = true; // the walk happens here in the naive form\n        // scan 3: consumer-count map, rebuilt per call.\n        let mut counts: Counts = HashMap::new();\n        for (i, node) in graph.nodes.iter().enumerate() {\n            if node.op == Op::MulMat {\n                if let Some(src1) = node.src1 {\n                    *counts.entry(src1).or_default()[node.ty.min(NTYPES - 1)] += 1;\n                }\n            }\n            let _ = i;\n        }\n        let _ = visiting; // the naive form ignores the posture\n        run_or_capture(graph, props_changed, &counts);\n    } else {\n        run_eager(graph);\n    }\n}\n\n#[test]\nfn the_naive_path_walks_every_node_even_on_replay() {\n    let g = Graph { nodes: (0..64).map(|i| Node { op: Op::MulMat, ty: 0, src1: Some(NodeId(i)) }).collect() };\n    // on replay (visiting = false) the naive form still walks all nodes\n    // three times — the dead host work this rule removes.\n    evaluate(&g, false);\n}\n".to_string(),
            opt_pattern: "// opt_pattern: (1) the compatibility verdict is MEMOIZED on a token\n// that is minted only AFTER the check has passed for this exact graph\n// object; (2) the consumer map is built only in the postures whose code\n// reads it. Replay performs zero node walks; every skipped scan is\n// host-only, so outputs are byte-identical by construction.\n#![allow(dead_code)]\n\nuse std::collections::HashMap;\n\nconst NTYPES: usize = 4;\n\n#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]\nstruct NodeId(usize);\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Op { MulMat, View, Other }\n\nstruct Node {\n    op: Op,\n    ty: usize,\n    src1: Option<NodeId>,\n}\n\nstruct Graph {\n    nodes: Vec<Node>,\n    uid: u64, // monotone per object; 0 = never assigned (the sentinel)\n}\n\nstruct GraphCache {\n    uid: u64, // written ONLY at the mint site, after a proven pass\n}\n\ntype Counts = HashMap<NodeId, [u32; NTYPES]>;\n\nfn check_compability(graph: &Graph) -> bool {\n    graph.nodes.iter().all(|n| match n.op {\n        Op::View | Op::Other => true,\n        Op::MulMat => n.src1.is_some(),\n    })\n}\n\nfn run_or_capture(_graph: &Graph, _props_changed: bool, _counts: &Counts) {}\nfn run_eager(_graph: &Graph) {}\n\nfn evaluate(graph: &Graph, cache: &mut GraphCache, replay: bool) {\n    // memo hit: same object (monotone uid), immutable node list, pure\n    // predicate => the scan's answer. Miss paths (uid == 0, mismatch)\n    // fall through to the scan and re-mint.\n    let compatible =\n        graph.uid != 0 && graph.uid == cache.uid || check_compability(graph);\n\n    if compatible {\n        // scan 2 (the property walk) decides the re-capture; its pass is\n        // the MINT SITE: the token is written only after the proof ran.\n        let props_changed = graph.uid != cache.uid;\n        if props_changed {\n            cache.uid = graph.uid;\n        }\n\n        // the map's readers live only under node visits: build exactly\n        // when the visiting posture runs (eager, or capture pass).\n        let visiting = !replay || props_changed;\n        let counts: Counts = if visiting {\n            let mut m: Counts = HashMap::new();\n            for node in &graph.nodes {\n                if node.op == Op::MulMat {\n                    if let Some(src1) = node.src1 {\n                        *m.entry(src1).or_default()[node.ty.min(NTYPES - 1)] += 1;\n                    }\n                }\n            }\n            m\n        } else {\n            HashMap::new() // replay: never read, never built\n        };\n        run_or_capture(graph, props_changed, &counts);\n    } else {\n        run_eager(graph);\n    }\n}\n\n#[test]\nfn the_memo_hits_only_after_a_proven_pass() {\n    let g = Graph { uid: 7, nodes: (0..64).map(|i| Node { op: Op::MulMat, ty: 0, src1: Some(NodeId(i)) }).collect() };\n    let mut cache = GraphCache { uid: 0 }; // nothing proven yet\n    // first call: the memo misses (uid 0), the scan runs, the mint fires.\n    evaluate(&g, &mut cache, false);\n    assert_eq!(cache.uid, 7);\n    // second call at the same object: the memo hits — no re-scan.\n    evaluate(&g, &mut cache, false);\n}\n\n#[test]\nfn replay_builds_no_consumer_map() {\n    let g = Graph { uid: 7, nodes: (0..64).map(|i| Node { op: Op::MulMat, ty: 0, src1: Some(NodeId(i)) }).collect() };\n    let mut cache = GraphCache { uid: 7 }; // already proven\n    // a pure replay (no re-capture): the visiting disjunction is false,\n    // the map stays empty, and the output path is unchanged.\n    evaluate(&g, &mut cache, true);\n}\n".to_string(),
        },
    ]
}
